#pragma once

#include <utility>

#include <juce_core/juce_core.h>

#include "../base/LabelAndAddress.h"

namespace disark
{

/**
 * Imports symbols from a human-readable symbol file, such as the ones generated by Rasm.
 */
class SymbolImporter
{
public:
    /**
     * Constructor.
     * @param inputStream the stream to import.
     */
    explicit SymbolImporter(juce::InputStream& inputStream) noexcept;

    /**
     * Imports the labels and their address from the input stream.
     * @param labelIndex the index of where the label is in the Strings.
     * @param addressIndex the index of where the address is in the Strings.
     * @return the labels and addresses. The string is the error, empty if no error occurred.
     */
    std::pair<std::vector<LabelAndAddress>, juce::String> import(int labelIndex = 0, int addressIndex = 1) const noexcept;

private:
    /**
     * Parses the given String. It must not be empty.
     * @param string the String to parse.
     * @param labelIndex the index of where the label is in the Strings.
     * @param addressIndex the index of where the address is in the Strings.
     * @param linePosition the position of the line (>= 1).
     * @return the label and address. The String is an error String, and must be empty if no error occurred.
     */
    static std::pair<LabelAndAddress, juce::String> parseString(const juce::String& string, int labelIndex, int addressIndex, int linePosition) noexcept;

    juce::InputStream& inputStream;                               //  The stream to import.
};

}    // namespace disark
